    .product-copy { color: #61566d; font-size: 12px; line-height: 1.5; max-width: 28ch; margin-top: 6px; }
    .tone { padding: 0 2px; display: grid; gap: 5px; }
    .tone-label { font-weight: 700; font-size: 13px; }
    .tone-scale { display: flex; justify-content: space-between; gap: 6px; color: var(--muted); font-size: 11px; }
    .tone ryugi-segmented, ryugi-textarea { display: block; width: 100%; }

    .note-entry { margin-top: 26px; padding: 19px 0 22px; border-top: 1px solid var(--line); }
    .note-entry h2 { font-size: 30px; margin-bottom: 10px; }

    .summary-card {
      display: block;
      background: #efe9f8;
      border: 1px solid #e1d6f0;
      border-radius: 14px;
      padding: 21px 24px 23px;
    }
    .summary-head { display: flex; justify-content: space-between; align-items: center; gap: 12px; margin-bottom: 15px; }
