    .ratings { gap: 5px; margin: 0; }
    .ratings div { display: flex; align-items: baseline; gap: 6px; flex-wrap: wrap; }
    .ratings dt { font-weight: 700; }
    .ratings dd { margin: 0; font-variant-numeric: tabular-nums; }
    .placeholder { color: var(--muted); }

    @media (max-width: 1000px) {
      .orbit { right: 5px; width: 180px; opacity: .55; }
    }
    @media (max-width: 760px) {
      main { width: min(540px, calc(100% - 32px)); padding-top: 23px; }
      .intro { padding: 25px 0; }
      .orbit { display: none; }
      h1 { font-size: clamp(48px, 11vw, 72px); }
      .section-head { align-items: start; flex-direction: column; }
      .previews { grid-template-columns: 1fr; gap: 21px; }
      .empty-state { min-height: 165px; }
      .summary-card { padding: 18px; }
      .summary-layout { grid-template-columns: 1fr; gap: 11px; }
      .summary-section, .summary-section:first-child { border-left: 0; padding: 0; }
      .summary-section + .summary-section { border-top: 1px solid #dcd0eb; padding-top: 11px; }
      .ratings { max-width: 260px; }
    }
  </style>
</head>
<body>
  <main>
    <header class="masthead">
      <ryugi-icon name="file-text" size="18" aria-hidden="true"></ryugi-icon>
      <span>Copy review</span>
    </header>

    <section class="intro" aria-labelledby="page-title">
      <p class="eyebrow">Search results</p>
      <h1 id="page-title">When search <em>comes up empty.</em></h1>
      <p>Compare three drafts, choose your favorite, and rate how each one sounds.</p>
      <div class="orbit" aria-hidden="true"><ryugi-icon name="search" size="38" stroke-width="1.5"></ryugi-icon></div>
    </section>

    <section class="comparison" aria-labelledby="compare-title">
      <div class="section-head">
        <h2 id="compare-title">Compare the drafts</h2>
        <div class="preference">
          <span id="preference-label">Preferred draft</span>
          <ryugi-segmented id="preferred-draft" value="none" variant="outlined" aria-labelledby="preference-label">
            <ryugi-segment value="none">None</ryugi-segment>
            <ryugi-segment value="a">A</ryugi-segment>
            <ryugi-segment value="b">B</ryugi-segment>
            <ryugi-segment value="c">C</ryugi-segment>
          </ryugi-segmented>
        </div>
      </div>

      <div class="previews">
        <article class="candidate" data-draft="a" aria-labelledby="heading-a">
          <ryugi-card class="preview-card" variant="borderless">
            <h3 class="candidate-heading" id="heading-a"><ryugi-tag color="purple" size="small">A</ryugi-tag><span>Direct</span></h3>
            <div class="product">
              <div class="product-toolbar"><div class="search-field"><ryugi-icon name="search" size="13" aria-hidden="true"></ryugi-icon> quarterly roadmap</div></div>
              <div class="empty-state">
                <div class="empty-icon"><ryugi-icon name="search-x" size="22" stroke-width="1.7" aria-hidden="true"></ryugi-icon></div>
                <div class="product-title">No results found</div>
                <p class="product-copy">Check your spelling or try different keywords.</p>
              </div>
            </div>
          </ryugi-card>
          <div class="tone">
            <span class="tone-label" id="tone-label-a">Tone rating <span class="visually-hidden"></span></span>
            <ryugi-segmented id="tone-a" value="unrated" block variant="outlined" aria-label="Tone rating for draft A">
              <ryugi-segment value="unrated" aria-label="Unrated">—</ryugi-segment>
              <ryugi-segment value="1">1</ryugi-segment><ryugi-segment value="2">2</ryugi-segment>
              <ryugi-segment value="3">3</ryugi-segment><ryugi-segment value="4">4</ryugi-segment>
              <ryugi-segment value="5">5</ryugi-segment>
            </ryugi-segmented>
            <div class="tone-scale"><span>1 · Off-tone</span><span>5 · On-tone</span></div>
          </div>
        </article>

        <article class="candidate" data-draft="b" aria-labelledby="heading-b">
          <ryugi-card class="preview-card" variant="borderless">
            <h3 class="candidate-heading" id="heading-b"><ryugi-tag color="purple" size="small">B</ryugi-tag><span>Conversational</span></h3>
            <div class="product">
              <div class="product-toolbar"><div class="search-field"><ryugi-icon name="search" size="13" aria-hidden="true"></ryugi-icon> quarterly roadmap</div></div>
              <div class="empty-state">
                <div class="empty-icon"><ryugi-icon name="search-x" size="22" stroke-width="1.7" aria-hidden="true"></ryugi-icon></div>
                <div class="product-title">We couldn’t find a match</div>
                <p class="product-copy">Try a shorter search or swap in a different word.</p>
              </div>
            </div>
          </ryugi-card>
          <div class="tone">
            <span class="tone-label">Tone rating</span>
            <ryugi-segmented id="tone-b" value="unrated" block variant="outlined" aria-label="Tone rating for draft B">
              <ryugi-segment value="unrated" aria-label="Unrated">—</ryugi-segment>
              <ryugi-segment value="1">1</ryugi-segment><ryugi-segment value="2">2</ryugi-segment>
              <ryugi-segment value="3">3</ryugi-segment><ryugi-segment value="4">4</ryugi-segment>
              <ryugi-segment value="5">5</ryugi-segment>
            </ryugi-segmented>
            <div class="tone-scale"><span>1 · Off-tone</span><span>5 · On-tone</span></div>
          </div>
        </article>

        <article class="candidate" data-draft="c" aria-labelledby="heading-c">
          <ryugi-card class="preview-card" variant="borderless">
            <h3 class="candidate-heading" id="heading-c"><ryugi-tag color="purple" size="small">C</ryugi-tag><span>Playful</span></h3>
            <div class="product">
              <div class="product-toolbar"><div class="search-field"><ryugi-icon name="search" size="13" aria-hidden="true"></ryugi-icon> quarterly roadmap</div></div>
              <div class="empty-state">
                <div class="empty-icon"><ryugi-icon name="search-x" size="22" stroke-width="1.7" aria-hidden="true"></ryugi-icon></div>
                <div class="product-title">Nothing turned up this time</div>
                <p class="product-copy">Give it another go with a more general search.</p>
              </div>
            </div>
          </ryugi-card>
          <div class="tone">
            <span class="tone-label">Tone rating</span>
            <ryugi-segmented id="tone-c" value="unrated" block variant="outlined" aria-label="Tone rating for draft C">
              <ryugi-segment value="unrated" aria-label="Unrated">—</ryugi-segment>
              <ryugi-segment value="1">1</ryugi-segment><ryugi-segment value="2">2</ryugi-segment>
              <ryugi-segment value="3">3</ryugi-segment><ryugi-segment value="4">4</ryugi-segment>
              <ryugi-segment value="5">5</ryugi-segment>
