            <div class="tone-scale"><span>1 · Off-tone</span><span>5 · On-tone</span></div>
          </div>
        </article>
      </div>
    </section>

    <section class="note-entry" aria-labelledby="note-title">
      <h2 id="note-title">Your note</h2>
      <ryugi-textarea id="review-note" rows="2" placeholder="What worked, or what would you change?" aria-labelledby="note-title"></ryugi-textarea>
    </section>

    <section aria-labelledby="summary-title">
      <ryugi-card class="summary-card" variant="borderless">
        <div class="summary-head">
          <h2 id="summary-title">Review summary</h2>
          <ryugi-tag id="rating-progress" size="small" color="purple">0 of 3 rated</ryugi-tag>
        </div>
        <div class="summary-layout">
          <div class="summary-section">
            <h3 class="eyebrow">Preferred draft</h3>
            <div id="summary-selection" class="summary-value placeholder" aria-live="polite">No draft selected</div>
            <p id="summary-copy" class="summary-value" hidden></p>
          </div>
          <div class="summary-section">
            <h3 class="eyebrow">Tone ratings</h3>
            <dl class="ratings summary-value">
              <div><dt>A</dt><dd id="score-a" class="placeholder">—</dd></div>
              <div><dt>B</dt><dd id="score-b" class="placeholder">—</dd></div>
              <div><dt>C</dt><dd id="score-c" class="placeholder">—</dd></div>
            </dl>
          </div>
          <div class="summary-section">
            <h3 class="eyebrow">Note</h3>
            <p id="summary-note" class="summary-value placeholder">No note yet</p>
          </div>
        </div>
      </ryugi-card>
    </section>
  </main>
  <script>
    document.addEventListener('"'ryugi-ui:ready', () => {
      const byId = (id) => document.getElementById(id);
      const selection = byId('preferred-draft');
      const note = byId('review-note');
      const candidates = [...document.querySelectorAll('.candidate')].map((preview) => {
        const key = preview.dataset.draft;
        return {
          key,
          preview,
          name: preview.querySelector('.candidate-heading span').textContent,
          headline: preview.querySelector('.product-title').textContent,
          rating: byId('tone-' + key),
          score: byId('score-' + key),
        };
      });
      const selectionSummary = byId('summary-selection');
      const copySummary = byId('summary-copy');
      const noteSummary = byId('summary-note');
      const progress = byId('rating-progress');
      const controls = new Set([selection, note, ...candidates.map(({ rating }) => rating)]);

      function render() {
        const chosen = candidates.find(({ key }) => key === selection.value);
        let ratedCount = 0;

        for (const candidate of candidates) {
          candidate.preview.toggleAttribute('data-selected', candidate === chosen);
          const rating = String(candidate.rating.value);
          const isRated = /"'^[1-5]$/.test(rating);
          candidate.score.textContent = isRated ? rating + '"' / 5' : '—';
          candidate.score.classList.toggle('placeholder', "'!isRated);
          ratedCount += Number(isRated);
        }

        selectionSummary.textContent = chosen ? chosen.key.toUpperCase() + '"' · ' + chosen.name : 'No draft selected';
        selectionSummary.classList.toggle('placeholder', "'!chosen);
        copySummary.hidden = !chosen;
        copySummary.textContent = chosen ? '"'“' + chosen.headline + '”' : '';

        const noteText = String(note.value ?? '').trim();
        noteSummary.textContent = noteText || 'No note yet';
        noteSummary.classList.toggle('placeholder', "'!noteText);
        progress.textContent = ratedCount + '"' of 3 rated';
      }

      document.addEventListener('ryugi-change', (event) => {
        if (controls.has(event.target)) render();
      });
      render();
    }, { once: true });
  </script>
</body>
</html>
